create table if not exists office.knowledge_items (id uuid primary key default gen_random_uuid(), org_id uuid not null references office.organizations(id), scope text not null check (scope in ('pixel','department','client','project')), department text, client_id uuid references office.clients(id), project_id uuid references office.projects(id), kind text not null default 'note', title text not null, body text not null, source_url text, valid_until date, owner_user uuid, approval_status text not null default 'pending' check (approval_status in ('pending','approved','rejected','expired')), version int not null default 1, tsv tsvector generated always as (to_tsvector('simple', coalesce(title,'')||' '||coalesce(body,''))) stored, created_by_agent text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz);
create index if not exists knowledge_tsv_idx on office.knowledge_items using gin(tsv);
create table if not exists office.files (id uuid primary key default gen_random_uuid(), org_id uuid not null references office.organizations(id), client_id uuid references office.clients(id), project_id uuid references office.projects(id), artifact_version_id uuid references office.artifact_versions(id), storage_bucket text not null default 'office', storage_path text not null unique, file_name text not null, mime text, size_bytes bigint, sha256 text, kind text, approved_for_use boolean not null default false, source_url text, uploaded_by uuid, created_at timestamptz not null default now(), archived_at timestamptz);

create table if not exists office.automations (id uuid primary key default gen_random_uuid(), org_id uuid not null references office.organizations(id), name text not null, trigger_type text not null check (trigger_type in ('schedule','event')), schedule_kind text, schedule_day int, schedule_weekday int, schedule_time time, timezone text not null default 'Asia/Jerusalem', event_key text, client_scope text not null default 'all_active' check (client_scope in ('all_active','selected','none')), client_ids uuid[], start_conditions jsonb not null default '{}'::jsonb, workflow_key text not null, params jsonb not null default '{}'::jsonb, limits jsonb not null default '{"max_tasks":60,"max_cost_usd":15}'::jsonb, status text not null default 'paused' check (status in ('active','paused')), last_run_at timestamptz, next_run_at timestamptz, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists office.automation_fires (automation_id uuid not null references office.automations(id), fire_key text not null, request_id uuid, fired_at timestamptz not null default now(), primary key (automation_id, fire_key));

create table if not exists office.usage_entries (id bigserial primary key, org_id uuid not null, client_id uuid, project_id uuid, agent_id text, task_run_id uuid, provider text not null, model text, cost_kind text not null check (cost_kind in ('reported','computed','estimate')), input_units numeric, output_units numeric, cost_usd numeric(10,4), note text, created_at timestamptz not null default now());
create table if not exists office.budgets (id uuid primary key default gen_random_uuid(), org_id uuid not null references office.organizations(id), scope_type text not null check (scope_type in ('org','client','agent','provider')), scope_ref text not null, monthly_limit_usd numeric(10,2) not null, hard_stop boolean not null default true, unique (org_id, scope_type, scope_ref));
create table if not exists office.budget_reservations (id uuid primary key default gen_random_uuid(), org_id uuid not null, task_run_id uuid not null, attempt int not null, amount_usd numeric(10,4) not null, status text not null default 'reserved' check (status in ('reserved','settled','released')), settled_usd numeric(10,4), created_at timestamptz not null default now(), unique (task_run_id, attempt));
create table if not exists office.kill_switches (org_id uuid not null, scope_type text not null check (scope_type in ('system','client','agent')), scope_ref text not null, active boolean not null default true, reason text, set_by uuid, set_at timestamptz not null default now(), primary key (org_id, scope_type, scope_ref));
create table if not exists office.audit_events (id bigserial primary key, org_id uuid, actor_type text not null check (actor_type in ('user','agent','system','worker','provider')), actor_id text, action text not null, entity text, entity_id text, before jsonb, after jsonb, created_at timestamptz not null default now());
create table if not exists office.notifications (id bigserial primary key, org_id uuid not null, user_id uuid, kind text not null, title text not null, link text, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists office.ui_layout (user_id uuid not null, key text not null, value jsonb not null, primary key (user_id, key));
create table if not exists office.worker_heartbeats (worker_id text primary key, kind text not null, last_seen timestamptz not null default now(), info jsonb);
create table if not exists office.system_secrets (name text primary key, sha256 text not null, rotated_at timestamptz not null default now());

revoke all on all tables in schema office from public, anon, authenticated;
